(function() {
    console.log('[stackinputhelper] main.min.js loaded');

    const config = Object.assign({
        apiurl: 'http://localhost:3001/recognize',
        sessionCreateUrl: 'http://localhost:3001/session/create',
        sessionResultBaseUrl: 'http://localhost:3001/session/',
        apitoken: '',
        uploadbtn: 'Upload math image',
        mobilebtn: 'Mobile Math Upload',
        uploading: 'Recognizing...',
        recognizefailed: 'Recognition failed.'
    }, window.STACKINPUTHELPER_CONFIG || {});

    const findAnswerBox = () => {
        const selectors = [
            'input[data-stack-input-type]',
            'textarea[data-stack-input-type]',
            'input[data-stack-input-decimalseparator]',
            'textarea[data-stack-input-decimalseparator]'
        ];

        for (const selector of selectors) {
            const candidates = Array.from(document.querySelectorAll(selector));
            const visible = candidates.find(el => el.offsetParent !== null);
            if (visible) {
                console.log('[stackinputhelper] found STACK input by selector:', selector, visible);
                return visible;
            }
        }

        console.warn('[stackinputhelper] no visible STACK input found');
        return null;
    };

    const createHiddenFileInput = () => {
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = 'image/*';
        fileInput.setAttribute('capture', 'environment');
        fileInput.style.display = 'none';
        document.body.appendChild(fileInput);
        return fileInput;
    };

    const setAnswerValue = (input, value) => {
        input.focus();
        input.value = value;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
    };

    const callRecognizer = async (file) => {
        const apiurl = config.apiurl || 'http://localhost:3001/recognize';

        const formData = new FormData();
        formData.append('image', file);

        const headers = {};
        if (config.apitoken) {
            headers['Authorization'] = 'Bearer ' + config.apitoken;
        }

        const response = await fetch(apiurl, {
            method: 'POST',
            body: formData,
            headers
        });

        if (!response.ok) {
            throw new Error('HTTP ' + response.status);
        }

        return await response.json();
    };

    const createReadonlyTextarea = (value = '') => {
        const ta = document.createElement('textarea');
        ta.value = value;
        ta.readOnly = true;
        ta.rows = 2;
        ta.style.width = '100%';
        ta.style.boxSizing = 'border-box';
        ta.style.marginTop = '4px';
        ta.style.marginBottom = '8px';
        ta.style.fontSize = '13px';
        ta.style.fontFamily = 'monospace';
        return ta;
    };

    const createEditableTextarea = (value = '') => {
        const ta = document.createElement('textarea');
        ta.value = value;
        ta.readOnly = false;
        ta.rows = 2;
        ta.style.width = '100%';
        ta.style.boxSizing = 'border-box';
        ta.style.marginTop = '4px';
        ta.style.marginBottom = '8px';
        ta.style.fontSize = '13px';
        ta.style.fontFamily = 'monospace';
        return ta;
    };

    const createResultPanel = () => {
        const panel = document.createElement('div');
        panel.style.marginTop = '8px';
        panel.style.padding = '8px';
        panel.style.border = '1px solid #ddd';
        panel.style.background = '#fafafa';
        panel.style.display = 'none';

        const rawTitle = document.createElement('div');
        rawTitle.textContent = 'OCR raw result:';
        rawTitle.style.fontWeight = 'bold';

        const rawTextarea = createReadonlyTextarea('');

        const stackTitle = document.createElement('div');
        stackTitle.textContent = 'STACK result:';
        stackTitle.style.fontWeight = 'bold';

        const stackTextarea = createEditableTextarea('');

        const applyBtn = document.createElement('button');
        applyBtn.type = 'button';
        applyBtn.textContent = 'Apply STACK result';
        applyBtn.style.padding = '4px 8px';
        applyBtn.style.cursor = 'pointer';

        panel.appendChild(rawTitle);
        panel.appendChild(rawTextarea);
        panel.appendChild(stackTitle);
        panel.appendChild(stackTextarea);
        panel.appendChild(applyBtn);

        panel._rawTextarea = rawTextarea;
        panel._stackTextarea = stackTextarea;
        panel._applyBtn = applyBtn;

        return panel;
    };

    const createMobilePanel = () => {
        const panel = document.createElement('div');
        panel.style.marginTop = '8px';
        panel.style.padding = '8px';
        panel.style.border = '1px solid #ddd';
        panel.style.background = '#f8fbff';
        panel.style.display = 'none';

        const title = document.createElement('div');
        title.textContent = 'Mobile Math Upload';
        title.style.fontWeight = 'bold';
        title.style.marginBottom = '8px';

        const tip = document.createElement('div');
        tip.textContent = 'Please use your mobile phone to scan the QR code, take a photo, and submit the results. The desktop will automatically receive them.';
        tip.style.marginBottom = '8px';

        const qrImg = document.createElement('img');
        qrImg.style.display = 'block';
        qrImg.style.maxWidth = '220px';
        qrImg.style.border = '1px solid #ddd';
        qrImg.style.marginBottom = '8px';

        const link = document.createElement('a');
        link.target = '_blank';
        link.rel = 'noopener noreferrer';
        link.style.wordBreak = 'break-all';
        link.style.display = 'block';
        link.style.marginBottom = '8px';

        const status = document.createElement('div');
        status.textContent = 'Session not created';
        status.style.color = '#555';

        panel.appendChild(title);
        panel.appendChild(tip);
        panel.appendChild(qrImg);
        panel.appendChild(link);
        panel.appendChild(status);

        panel._qrImg = qrImg;
        panel._link = link;
        panel._status = status;

        return panel;
    };

    const updateResultPanel = (panel, rawLatex, stackResult, answerBox) => {
        panel.style.display = 'block';
        panel._rawTextarea.value = rawLatex || '';
        panel._stackTextarea.value = stackResult || '';

        panel._applyBtn.onclick = () => {
            setAnswerValue(answerBox, panel._stackTextarea.value || '');
        };
    };

    const createMobileSession = async () => {
        const response = await fetch(config.sessionCreateUrl || 'http://localhost:3001/session/create', {
            method: 'POST'
        });

        if (!response.ok) {
            throw new Error('HTTP ' + response.status);
        }

        return await response.json();
    };

    const fetchSessionResult = async (sessionId) => {
        const base = config.sessionResultBaseUrl || 'http://localhost:3001/session/';
        const response = await fetch(base + sessionId + '/result');

        if (!response.ok) {
            throw new Error('HTTP ' + response.status);
        }

        return await response.json();
    };

    const buildQrUrl = (text) => {
        return 'https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=' + encodeURIComponent(text);
    };

    const attachButton = (answerBox) => {
        if (!answerBox) {
            return;
        }

        if (answerBox.dataset.stackinputhelperBound === '1') {
            return;
        }

        answerBox.dataset.stackinputhelperBound = '1';

        const fileInput = createHiddenFileInput();
        const resultPanel = createResultPanel();
        const mobilePanel = createMobilePanel();

        const uploadBtn = document.createElement('button');
        uploadBtn.type = 'button';
        uploadBtn.textContent = config.uploadbtn || 'Upload math image';
        uploadBtn.style.marginLeft = '8px';
        uploadBtn.style.padding = '4px 8px';
        uploadBtn.style.border = '1px solid #999';
        uploadBtn.style.background = '#f5f5f5';
        uploadBtn.style.cursor = 'pointer';

        const mobileBtn = document.createElement('button');
        mobileBtn.type = 'button';
        mobileBtn.textContent = config.mobilebtn || 'Mobile Math Upload';
        mobileBtn.style.marginLeft = '8px';
        mobileBtn.style.padding = '4px 8px';
        mobileBtn.style.border = '1px solid #999';
        mobileBtn.style.background = '#eef6ff';
        mobileBtn.style.cursor = 'pointer';

        uploadBtn.addEventListener('click', function() {
            fileInput.value = '';
            fileInput.click();
        });

        fileInput.addEventListener('change', async function() {
            const file = fileInput.files && fileInput.files[0];
            if (!file) {
                return;
            }

            const oldText = uploadBtn.textContent;
            uploadBtn.disabled = true;
            uploadBtn.textContent = config.uploading || 'Recognizing...';

            try {
                const result = await callRecognizer(file);
                const rawLatex = result.raw_latex || '';
                const stackResult = result.stack || result.normalized || result.text || '';

                if (!stackResult) {
                    throw new Error('Empty STACK result');
                }

                updateResultPanel(resultPanel, rawLatex, stackResult, answerBox);
                setAnswerValue(answerBox, stackResult);
            } catch (error) {
                console.error('[stackinputhelper] recognition failed:', error);
                alert((config.recognizefailed || 'Recognition failed.') + '\n' + error.message);
            } finally {
                uploadBtn.disabled = false;
                uploadBtn.textContent = oldText;
            }
        });

        mobileBtn.addEventListener('click', async function() {
            try {
                mobileBtn.disabled = true;
                mobileBtn.textContent = 'Creating session...';

                const data = await createMobileSession();
                if (!data.success || !data.session_id || !data.mobile_url) {
                    throw new Error('Invalid session response');
                }

                const sessionId = data.session_id;
                const mobileUrl = data.mobile_url;

                mobilePanel.style.display = 'block';
                mobilePanel._link.href = mobileUrl;
                mobilePanel._link.textContent = mobileUrl;
                mobilePanel._qrImg.src = buildQrUrl(mobileUrl);
                mobilePanel._status.textContent = 'Please use your mobile phone to scan the QR code and take a photo to upload. The desktop is waiting for the results...';

                mobileBtn.disabled = false;
                mobileBtn.textContent = config.mobilebtn || 'Mobile Math Upload';

                const start = Date.now();
                const timeoutMs = 5 * 60 * 1000;

                const timer = setInterval(async () => {
                    try {
                        const result = await fetchSessionResult(sessionId);

                        if (result.ready) {
                            clearInterval(timer);

                            const rawLatex = result.raw_latex || '';
                            const stackResult = result.stack || result.text || '';

                            mobilePanel._status.textContent = 'Successfully received mobile results.';
                            updateResultPanel(resultPanel, rawLatex, stackResult, answerBox);
                            setAnswerValue(answerBox, stackResult);
                        } else {
                            mobilePanel._status.textContent = 'Mobile results not yet submitted, continuing to wait...';
                        }

                        if (Date.now() - start > timeoutMs) {
                            clearInterval(timer);
                            mobilePanel._status.textContent = 'Timeout waiting for results, please create a new session.';
                        }
                    } catch (err) {
                        console.error('[stackinputhelper] polling failed:', err);
                    }
                }, 2000);

            } catch (error) {
                console.error('[stackinputhelper] mobile session failed:', error);
                alert('Failed to create mobile session: ' + error.message);
                mobileBtn.disabled = false;
                mobileBtn.textContent = config.mobilebtn || 'Mobile Math Upload';
            }
        });

        answerBox.insertAdjacentElement('afterend', uploadBtn);
        uploadBtn.insertAdjacentElement('afterend', mobileBtn);
        mobileBtn.insertAdjacentElement('afterend', mobilePanel);
        mobilePanel.insertAdjacentElement('afterend', resultPanel);
    };

    const run = () => {
        const answerBox = findAnswerBox();
        if (!answerBox) {
            return;
        }
        attachButton(answerBox);
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', run);
    } else {
        run();
    }
})();